function pj_media_url(array $pr,string $key): string{$rel=(string)($pr['profile'][$key]??'');if($rel==='')return '';if(strpos($rel,'storage/pr-media/')===0)return 'pr-media.php?pr_id='.(int)$pr['id'].'&field='.rawurlencode($key);return $rel;}
function pj_shift_status(string $s): string{return ['scheduled'=>'มีกะงาน','confirmed'=>'ยืนยันกะแล้ว','working'=>'กำลังทำงาน','completed'=>'จบกะ','off'=>'วันหยุด','cancelled'=>'ยกเลิก'][$s]??$s;}
