function pj_job_step(string $status): int{return ['assigned'=>1,'accepted'=>2,'in_service'=>3,'completed'=>4,'rejected'=>0][$status]??0;}
if($_SERVER['REQUEST_METHOD']==='POST'){
 pr_preview_block_post();
 csrf_check();$action=(string)($_POST['action']??'');
 try{
  if($action==='status'){
   $st=(string)($_POST['status']??'');if(!in_array($st,['online','break'],true))throw new RuntimeException('สถานะไม่ถูกต้อง');
   db_mutate(function($x)use($prId,$st,$uid){if(!attendance_open($x,$prId))throw new RuntimeException('ต้อง Check-in เข้าเวรก่อนเปลี่ยนสถานะ');foreach($x['checkins'] as $c)if((int)($c['pr_id']??0)===$prId&&in_array((string)($c['status']??''),['assigned','accepted','in_service'],true))throw new RuntimeException('กำลังมีงานอยู่ ไม่สามารถเปลี่ยนสถานะเองได้');foreach($x['prs'] as &$p)if((int)$p['id']===$prId)$p['status']=$st;unset($p);$x['audit'][]=['at'=>date('c'),'action'=>'pr_status','pr_id'=>$prId,'status'=>$st,'by'=>$uid];return $x;});$msg='เปลี่ยนสถานะเรียบร้อย';
  }elseif(in_array($action,['accept_job','reject_job','start_service','complete_job'],true)){
   $cid=(int)($_POST['checkin_id']??0);
   if($action==='accept_job')db_mutate(function($x)use($cid,$prId,$uid){foreach($x['checkins'] as &$c)if((int)$c['id']===$cid){if((int)($c['pr_id']??0)!==$prId||($c['status']??'')!=='assigned')throw new RuntimeException('งานนี้ไม่พร้อมให้รับ');$c['status']='accepted';$c['accepted_at']=date('c');$c['updated_at']=date('c');foreach($x['prs'] as &$p)if((int)$p['id']===$prId){$p['status']='busy';$p['current_checkin_id']=$cid;}unset($p);$x['audit'][]=['at'=>date('c'),'action'=>'pr_accept_job','checkin_id'=>$cid,'pr_id'=>$prId,'by'=>$uid];return $x;}unset($c);throw new RuntimeException('ไม่พบงาน');});
   if($action==='reject_job')db_mutate(function($x)use($cid,$prId,$uid){foreach($x['checkins'] as &$c)if((int)$c['id']===$cid){if((int)($c['pr_id']??0)!==$prId||($c['status']??'')!=='assigned')throw new RuntimeException('งานนี้ไม่พร้อมให้ปฏิเสธ');$c['status']='rejected';$c['rejected_at']=date('c');$c['updated_at']=date('c');$c['pr_id']=null;foreach($x['prs'] as &$p)if((int)$p['id']===$prId){$p['status']=attendance_open($x,$prId)?'online':'offline';$p['current_checkin_id']=null;}unset($p);$x['audit'][]=['at'=>date('c'),'action'=>'pr_reject_job','checkin_id'=>$cid,'pr_id'=>$prId,'by'=>$uid];return $x;}unset($c);throw new RuntimeException('ไม่พบงาน');});
   if($action==='start_service')db_mutate(function($x)use($cid,$prId,$uid){foreach($x['checkins'] as &$c)if((int)$c['id']===$cid){if((int)($c['pr_id']??0)!==$prId||($c['status']??'')!=='accepted')throw new RuntimeException('งานนี้ยังไม่พร้อมเริ่มบริการ');$c['status']='in_service';$c['started_at']=date('c');$c['updated_at']=date('c');$x['audit'][]=['at'=>date('c'),'action'=>'pr_start_service','checkin_id'=>$cid,'pr_id'=>$prId,'by'=>$uid];return $x;}unset($c);throw new RuntimeException('ไม่พบงาน');});
   if($action==='complete_job')db_mutate(function($x)use($cid,$prId,$uid){foreach($x['checkins'] as &$c)if((int)$c['id']===$cid){if((int)($c['pr_id']??0)!==$prId||!in_array((string)$c['status'],['accepted','in_service'],true))throw new RuntimeException('งานนี้ไม่พร้อมปิด');$tableId=(int)($c['table_id']??0);$c['status']='completed';$c['completed_at']=date('c');$c['updated_at']=date('c');foreach($x['prs'] as &$p)if((int)$p['id']===$prId){$p['status']=attendance_open($x,$prId)?'online':'offline';$p['current_checkin_id']=null;}unset($p);foreach($x['tables'] as &$t)if((int)$t['id']===$tableId)$t['status']='available';unset($t);$x['audit'][]=['at'=>date('c'),'action'=>'pr_complete_job','checkin_id'=>$cid,'pr_id'=>$prId,'by'=>$uid];return $x;}unset($c);throw new RuntimeException('ไม่พบงาน');});
   $msg='อัปเดตงานเรียบร้อย';
  }elseif($action==='read_notifications'){
   db_mutate(function($x)use($uid){foreach($x['notifications'] as &$n)if(empty($n['read_at'])&&(int)($n['user_id']??0)===$uid)$n['read_at']=date('c');unset($n);return $x;});$msg='อ่านการแจ้งเตือนทั้งหมดแล้ว';
  }
 }catch(Throwable $e){$err=$e->getMessage();}
 $d=db_load();$pr=user_pr($d,(int)$u['id']);
}
