$activeJobs=array_values(array_filter($d['checkins']??[],function($c)use($prId){return (int)($c['pr_id']??0)===$prId&&in_array((string)($c['status']??''),['assigned','accepted','in_service'],true);}));
usort($activeJobs,function($a,$b){return strcmp((string)($b['updated_at']??''),(string)($a['updated_at']??''));});
$rejectedIds=[];foreach($d['audit']??[] as $a)if(($a['action']??'')==='pr_reject_job'&&(int)($a['pr_id']??0)===$prId)$rejectedIds[(int)($a['checkin_id']??0)]=1;
$history=[];foreach($d['checkins']??[] as $c){$id=(int)($c['id']??0);$mine=(int)($c['pr_id']??0)===$prId||isset($rejectedIds[$id]);if(!$mine)continue;if(!in_array((string)($c['status']??''),['completed','rejected'],true))continue;$history[]=$c;}
usort($history,function($a,$b){return strcmp((string)($b['updated_at']??$b['completed_at']??''),(string)($a['updated_at']??$a['completed_at']??''));});$history=array_slice($history,0,12);
